from admissions_records import *

skills=['reading','writing','listening','speaking']
unknown={'satPolicy':'unknown','note':L('The applicable SAT/ACT policy for the applicant’s school qualification remains unconfirmed. Language-test alternatives do not establish an academic-test waiver.','Правило SAT/ACT для школьной квалификации кандидата пока не подтверждено. Альтернативы языкового теста не устанавливают освобождение от академических экзаменов.')}
def english(min,sections,variant='IELTS Academic'):
 return {'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':min,'sections':sections,'variant':variant,'role':'admission'}}
def src(url,en,ru):return S(url,L(en,ru),access='web-html-read')
gaps=['Fall 2027-specific applicability, exact programme exceptions and qualification-specific SAT/ACT rules need further confirmation.']

bs=[src('https://brocku.ca/admissions/english-proficiency/','Brock undergraduate English proficiency and exceptions','Brock: английский бакалавриата и исключения')]
be=english(6.5,dict.fromkeys(skills,6),'IELTS Academic / online; One Skill Retake accepted')
be.update(alternatives=L('Duolingo 110; CAEL 70 with each component 60; PTE 58; Cambridge 176. TOEFL legacy 88 with each component 21. The new-scale table gives overall 4.5, Reading/Speaking 4.0 and Writing/Listening 4.5; the page dates its change 1 January 2026, so confirm the test-date category.','Duolingo 110; CAEL 70 с каждой секцией 60; PTE 58; Cambridge 176. Прежний TOEFL 88 с каждой секцией 21. В новой таблице общий 4,5, Reading/Speaking 4,0 и Writing/Listening 4,5; страница датирует изменение 1 января 2026, поэтому уточните категорию даты теста.'),waiver=L('A waiver request may be reviewed after three full-time English-medium years without ESL and supporting evidence, or an eligible IB English A qualification. Exemption is not automatic.','Запрос освобождения могут рассмотреть после трёх лет очного обучения на английском без ESL с документами либо по подходящей квалификации IB English A. Освобождение не автоматическое.'),note=L('General undergraduate rule excludes co-op Accounting. IELP level 5 completion is a separate conditional pathway, not this direct-entry score.','Общее бакалаврское правило исключает co-op Accounting. Завершение IELP level 5 — отдельный условный маршрут, а не этот балл прямого приёма.'))
record('brock-university',[route(id='general-undergraduate',english=be,academic=unknown,sources=bs),route(id='coop-accounting',label=L('Co-op Accounting BAcc: language requirement','Co-op Accounting BAcc: языковое требование'),programmeIds=['business'],english=english(7,dict.fromkeys(skills,6.5)),academic=unknown,sources=bs)],'Separated standard English 6.5/6 from co-op Accounting 7/6.5 and documented waiver review and TOEFL date ambiguity.',gaps)

ms=[src('https://www.mtroyal.ca/Admission/AdmissionRequirements/english-language-proficiency-requirement-institutional.htm','Mount Royal institutional undergraduate English proficiency','Mount Royal: английский бакалаврского приёма')]
me=english(6.5,dict.fromkeys(skills,5.5),'IELTS Academic / IELTS Academic Online')
me.update(toefl={'accepted':True,'scales':[{'period':'pre2026','min':86,'sections':dict.fromkeys(skills,20)},{'period':'post2026','min':4.5,'sections':dict.fromkeys(skills,4)}]},alternatives=L('Duolingo 120; PTE Academic including online 58 with each skill 55; CAEL 70/60; Cambridge 176; MET 62/53; LanguageCert 70/60; LEAP level 4 with B− (80%).','Duolingo 120; PTE Academic, включая онлайн, 58 и каждый навык 55; CAEL 70/60; Cambridge 176; MET 62/53; LanguageCert 70/60; LEAP level 4 с B− (80%).'),waiver=L('Two full-time years of English-medium education in a listed English-speaking country, with the required English Language Arts 30-1/30-2 or equivalent. Country, school history and academic English prerequisite must all be checked.','Два года очного обучения на английском в указанной англоязычной стране с требуемым English Language Arts 30-1/30-2 либо эквивалентом. Нужно проверить страну, историю обучения и академический английский предмет.'),note=L('Language proficiency and the programme’s required school English course are separate requirements. A lower LEAP entry score is not a bachelor admission minimum.','Языковое подтверждение и обязательный школьный английский предмет программы — разные требования. Более низкий входной балл LEAP не является минимумом бакалаврского приёма.'))
record('mount-royal-university',[route(english=me,academic=unknown,sources=ms)],'Added exact section minima, two TOEFL scales and the separate school-English prerequisite.',gaps)

ac=[src('https://www2.acadiau.ca/admissions/application-process/international-students.html','Acadia international undergraduate English requirements','Acadia: английский иностранных бакалавров')]
ae=english(6.5,dict.fromkeys(skills,6),'IELTS; Academic variant not specified in this table')
ae.update(toefl={'accepted':True,'scales':[{'period':'pre2026','min':90,'sections':dict.fromkeys(skills,20)},{'period':'post2026','min':4.5,'sections':dict.fromkeys(skills,4.5)}]},alternatives=L('CAEL 70/60; PTE Academic 61/60; Cambridge C1 Advanced or B2 First 180/173; Duolingo 115 with each subscore 90; LanguageCert 70–74/65; Oxford Advanced 135.','CAEL 70/60; PTE Academic 61/60; Cambridge C1 Advanced либо B2 First 180/173; Duolingo 115 с каждым подбаллом 90; LanguageCert 70–74/65; Oxford Advanced 135.'),waiver=L('Three years of English-medium instruction may qualify for a waiver; the university evaluates international qualifications individually.','Три года обучения на английском могут дать право на освобождение; иностранные квалификации оцениваются индивидуально.'))
record('acadia-university',[route(english=ae,academic=unknown,sources=ac)],'Preserved IELTS 6.5 with each band 6 and the new TOEFL each-band requirement, separately from waiver eligibility.',gaps)

os=[src('https://www.uottawa.ca/study/undergraduate-studies/language-requirements','Ottawa English/French undergraduate language routes','Ottawa: английские и французские языковые маршруты')]
oe=english(6.5,{'writing':6.5},'IELTS Academic; One Skill Retake accepted')
oe.update(toefl={'accepted':True,'scales':[{'period':'pre2026','min':86,'sections':{'writing':22}},{'period':'post2026','min':4.5,'sections':{'writing':4.5}}]},alternatives=L('Duolingo 120 with Literacy 120; recognised school qualifications; approved TOEFL options. Lower EIP language-preparation scores are not unconditional degree entry.','Duolingo 120 с Literacy 120; признанные школьные квалификации; одобренные варианты TOEFL. Более низкие баллы языковой подготовки EIP не являются безусловным поступлением на степень.'),waiver=L('Three full-time English-only years, apart from language classes, in a country where English is official; specified school qualifications may also qualify. Citizenship alone is not sufficient.','Три очных года только на английском, кроме языковых предметов, в стране, где английский официальный; могут подойти и указанные школьные квалификации. Одного гражданства недостаточно.'))
record('university-of-ottawa',[route(id='english-direct',label=L('English-language degree entry without ESL condition','Англоязычная степень без условия ESL'),english=oe,academic=unknown,sources=os),route(id='english-with-esl',kind='degree-with-esl',label=L('English-language degree entry with compulsory ESL','Англоязычная степень с обязательным ESL'),english=english(6,{},'IELTS Academic'),academic=unknown,sources=os,note=L('The 6.0 category requires extra English courses; it does not meet the 6.5 overall/Writing unconditional rule. Other EIP preparatory categories have separate band conditions.','Категория 6,0 требует дополнительных курсов английского; это не безусловное правило 6,5 overall/Writing. У других подготовительных категорий EIP отдельные условия секций.')),route(id='french-direct',language='fr',label=L('French-language undergraduate entry','Франкоязычный бакалаврский приём'),localLanguage=[{'name':'French','requirement':L('DALF C1/C2; DELF B2 with Writing 16/25; recognised TCF/TEF B2 categories. Three French-only years in an eligible French-official country may qualify for a waiver. Programme and certificate categories matter.','DALF C1/C2; DELF B2 с Writing 16/25; признанные категории TCF/TEF B2. Три года только на французском в подходящей стране с официальным французским могут дать освобождение. Важны программа и категория сертификата.')}],academic=unknown,sources=os)],'Separated English 6.5/Writing 6.5, degree with ESL 6.0, preparatory EIP and French evidence.',gaps)

sh='https://www.usherbrooke.ca/admission/da/exigences-linguistiques/exigences-relatives-a-la-langue-francaise-pour-admission'
record('universite-de-sherbrooke',[route(id='engineering-french',language='fr',programmeIds=['engineering'],label=L('Listed engineering bachelor programmes: French admission condition','Перечисленные инженерные бакалаврские программы: французский для поступления'),localLanguage=[{'name':'French','requirement':L('Biotechnology, chemical, civil, building, electrical, computer and mechanical engineering: C1 in all four skills in the general table. The programme page prevails. Approved French schooling may exempt; recognised tests include DELF/DALF, TCF with oral/written components and TEF variants. TFI/SEL are not recognised.','Biotechnology, chemical, civil, building, electrical, computer и mechanical engineering: C1 во всех четырёх навыках в общей таблице. Страница программы имеет приоритет. Подходящее французское образование может освобождать; принимаются DELF/DALF, TCF с устной/письменной частями и варианты TEF. TFI/SEL не признаются.')}],academic=unknown,sources=[src(sh,'Sherbrooke programme-specific French admission table','Sherbrooke: французский для поступления по программам')])],'Replaced a generic unknown IELTS with the scoped French engineering requirement; did not assign engineering C1 to Computer Science.', ['Exact 2027 programme page, non-engineering language requirements, alternative-test score mappings and academic qualifications remain to be checked.'])

mu='https://www.umoncton.ca/gouvernance/sites/gouvernance.prod.umoncton.ca/files/politiques/UMoncton-politique-linguistique-mai-2025.pdf'
record('universite-de-moncton',[route(id='french-undergraduate',language='fr',label=L('French-language undergraduate study: May 2025 policy','Франкоязычный бакалавриат: политика мая 2025'),localLanguage=[{'name':'French','requirement':L('French is the teaching and assessment language, with named exceptions. Sufficient French is an admission condition; French immersion applicants have an oral interview and regular-status oral/written evaluation. The DELF B2 line in Annex B is specifically a BEd condition, not a universal bachelor cutoff.','Французский — язык преподавания и оценивания, с названными исключениями. Достаточный французский — условие поступления; для French immersion предусмотрены устное интервью и устная/письменная оценка для обычного статуса. Строка DELF B2 приложения B относится именно к BEd, а не ко всем бакалаврам.')}],academic=unknown,sources=[S(mu,L('Moncton adopted linguistic policy, Annex B','Moncton: принятая языковая политика, приложение B'),pages=[1,4,7,16],access='web-pdf-read')])],'Scoped the French-medium route and prevented the BEd-specific DELF B2 condition from becoming a university-wide IELTS substitute.', ['Fall 2027 programme-specific French evidence, section scores and school-qualification academic rules remain unconfirmed.'])
for r in records['brock-university']['routes']:
 r['academic']={'satPolicy':'accepted','note':L('Faculty Handbook 3.3.3(c): SAT can support borderline US Grade 12 diploma applications. This establishes SAT acceptance in that scope, not an ACT alternative, a universal test-optional rule or a Fall 2027 requirement.','Faculty Handbook 3.3.3(c): SAT может поддержать пограничную заявку с американским Grade 12 diploma. Это подтверждает приём SAT в этой области, а не альтернативу ACT, универсальную test-optional политику или требование Fall 2027.')}
 r['sources'].append(src('https://brocku.ca/university-secretariat/faculty-handbook/section-3/','Brock Faculty Handbook 3.3.3(c): US diploma and SAT','Brock Faculty Handbook 3.3.3(c): диплом США и SAT'))
finish()
